   182→export const getPlanByName = (name: string): MyCryptoPilotPlan => {
   183→  return (
   184→    MYCRYPTOPILOT_PLANS.find((p) => p.name === name) ?? MYCRYPTOPILOT_PLANS[0]
   185→  );
   186→};
   187→
   188→export const getPlanLimits = (
   189→  plan: MyCryptoPilotPlanName = "free",
   190→): MyCryptoPilotPlan["limits"] => {
   191→  const planData = getPlanByName(plan);
   192→  return planData.limits;
   193→};
   194→
   195→/**
   196→ * Check if a user can perform an action based on their plan
   197→ */
   198→export const canPerformAction = (
   199→  plan: MyCryptoPilotPlanName,
   200→  action: keyof MyCryptoPilotPlan["limits"],
   201→): boolean => {
   202→  const limits = getPlanLimits(plan);
   203→  const value = limits[action];
   204→
   205→  if (typeof value === "boolean") {
   206→    return value;
   207→  }
   208→
   209→  // For numeric values, we just return true if > 0
   210→  // The actual counting/limiting should be done in the business logic
   211→  return value > 0;
   212→};
   213→
   214→/**
   215→ * Calculate days granted based on amount paid
   216→ */
   217→export const calculateDaysGranted = (
   218→  amountUSD: number,
   219→  plan: MyCryptoPilotPlanName,
   220→): number => {
   221→  const planData = getPlanByName(plan);
   222→  const baseDays = 30;
   223→
   224→  // Test plan grants 0 days (no subscription activation)
   225→  if (plan === "test") {
   226→    return 0;
   227→  }
   228→
   229→  if (planData.priceUSD === 0) {
   230→    return 0;
   231→  }
   232→
   233→  // Pro-rata: if user pays half the price, they get 15 days
   234→  const ratio = amountUSD / planData.priceUSD;
   235→  return Math.floor(ratio * baseDays);
   236→};
   237→
   238→/**
   239→ * Get plan from price amount (useful for payment detection)
   240→ */
   241→export const getPlanFromAmount = (amountUSD: number): MyCryptoPilotPlanName => {
   242→  // Test payment: exactly 1 USD (with small tolerance for crypto precision)
   243→  if (amountUSD >= 0.95 && amountUSD <= 1.05) {
   244→    return "test";
   245→  }
   246→
   247→  // Match to closest plan based on price (with 5% tolerance)
   248→  const tolerance = 0.05;
   249→
   250→  for (const plan of MYCRYPTOPILOT_PLANS) {
   251→    if (plan.priceUSD === 0 || plan.name === "test") continue;
   252→
   253→    const minPrice = plan.priceUSD * (1 - tolerance);
   254→    const maxPrice = plan.priceUSD * (1 + tolerance);
   255→
   256→    if (amountUSD >= minPrice && amountUSD <= maxPrice) {
   257→      return plan.name;
   258→    }
   259→  }
   260→
   261→  // Default to pro if no match found
   262→  return "pro";
   263→};
